const prompt = `
You are a Senior AI Solutions Consultant.

Create a professional client proposal based on the workflow details below.

Client Requirement:
${$json.requirement}

Most Similar Workflow:
${$json.workflow_name}

Workflow Analysis

Search Score:
${$json.search_score}

Project Rating:
${$json.project_rate}

Business Value:
${$json.business_value}

Difficulty:
${$json.difficulty}

Estimated Development Hours:
${$json.estimated_hours}

Automation Level:
${$json.automation_level}

Market Insight:
${$json.market_reason}

Generate a professional proposal.

Return ONLY valid JSON.

{
  "proposal_title":"",
  "project_summary":"",
  "scope_of_work":"",
  "deliverables":"",
  "timeline":"",
  "pricing":"",
  "technologies":"",
  "assumptions":"",
  "next_steps":""
}
`;

return [
  {
    json: {
      payload: {
        contents: [
          {
            parts: [
              {
                text: prompt
              }
            ]
          }
        ]
      }
    }
  }
];

const text = $json.candidates?.[0]?.content?.parts?.[0]?.text;

if (!text) {
  throw new Error("Gemini response not found.");
}

// Remove markdown if Gemini returns ```json ... ```
const _s = text.indexOf("{"), _e = text.lastIndexOf("}");
const clean = (_s >= 0 && _e > _s ? text.slice(_s, _e + 1) : text).trim(); // tolerate prose around the JSON

let proposal;

try {
  proposal = JSON.parse(clean);
} catch (err) {
  throw new Error(
    "Failed to parse Gemini JSON.\n\nResponse:\n" + clean
  );
}

// Get previous workflow data
const previous = $("Code (Extract Top Workflow)1").first().json;

return [
  {
    json: {
      requirement: previous.requirement,
      workflow_name: previous.workflow_name,
      search_score: previous.search_score,

      project_rate: previous.project_rate,
      business_value: previous.business_value,
      difficulty: previous.difficulty,
      estimated_hours: previous.estimated_hours,
      automation_level: previous.automation_level,

      proposal_title: proposal.proposal_title,
      project_summary: proposal.project_summary,
      scope_of_work: proposal.scope_of_work,
      deliverables: proposal.deliverables,
      timeline: proposal.timeline,
      pricing: proposal.pricing,
      technologies: proposal.technologies,
      assumptions: proposal.assumptions,
      next_steps: proposal.next_steps,

      created_at: new Date().toISOString()
    }
  }
];

const vector = $json.embedding?.values;

if (!vector || !Array.isArray(vector)) {
	throw new Error("Embedding vector not found.");
}

const requirement = $("Code (Build Gemini Embedding Payload)")
	.first()
	.json.requirement;

return [
	{
		json: {
			requirement,
			vector,
			vector_dimension: vector.length
		}
	}
];

const MIN_SCORE = 0.55; // ignore weak matches instead of consulting the LLM about an unrelated workflow
const results = $json.result || [];
if (!results.length) throw new Error("No similar workflow found in Qdrant.");

// Qdrant returns CHUNKS: pick the best chunk, but never trust a weak one
const best = results[0];
if ((best.score || 0) < MIN_SCORE) {
  throw new Error(`Best match score ${best.score} is below ${MIN_SCORE}. No relevant workflow in the knowledge base.`);
}
const payload = best.payload || {};
// Market fields live on every chunk of the workflow after Project 2 runs; fall back to any chunk that has them
const withMarket = results.find(r => r.payload && r.payload.workflow_name === payload.workflow_name && r.payload.project_rate != null) || best;
const m = withMarket.payload || {};

return [{
  json: {
    requirement: $("Code (Extract Embedding)1").first().json.requirement,
    workflow_name: payload.workflow_name || "",
    search_score: best.score || 0,
    project_rate: m.project_rate ?? 0,
    business_value: m.business_value ?? 0,
    difficulty: m.difficulty || "",
    estimated_hours: m.estimated_hours ?? 0,
    automation_level: m.automation_level || "",
    market_reason: m.market_reason || ""
  }
}];

const BRAND = "Your Company Name"; // shown in the proposal header/footer
const d = $json;
// --- safe rendering helpers (model output is untrusted: escape before putting it into HTML) ---
const esc = (s) => String(s ?? "").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;");
const fmt = (v) => {
  if (Array.isArray(v)) return "<ul>" + v.map(x => "<li>" + fmt(x) + "</li>").join("") + "</ul>";
  if (v && typeof v === "object") return "<ul>" + Object.entries(v).map(([k,x]) => "<li><strong>" + esc(k) + ":</strong> " + fmt(x) + "</li>").join("") + "</ul>";
  return esc(v).replace(/\n/g,"<br>");
};


